package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class EquivalentFractionPicturesTest {
 @Test public void all156PublicConditionsHaveFourBlankCountsAndNoAnswerTransfer(){int count=0;for(int d=2;d<=12;d++)for(int n=1;n<d;n++)for(int b=2;b<=12;b++)if(d!=b&&n*b%d==0)for(boolean den:List.of(false,true)){Question q=EquivalentFractionPictures.make(n,d,b,den);q.answers=new String[]{"999"};q.expression="999";q.diagram=new StudyDiagram("poison",new double[]{999});int expected=den?b:n*b/d;assertTrue(new Checker().check(q,List.of(),List.of(""+expected)).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of(""+(expected+1))).status);HelpPlan p=HelpPlan.forQuestion(q);assertFalse(p.canTransfer());assertEquals(4,p.size());assertTrue(p.restore(null,q.id).entries.stream().allMatch(String::isEmpty));int[] inputs={d,n,b,n*b/d};for(int i=0;i<4;i++)assertTrue(p.step(i).accepts(""+inputs[i]));assertArrayEquals(new double[]{n,d,b},q.diagram.values,0);count++;}assertEquals(156,count);}
 @Test public void actualGradeThreeExhausts156BeforeOldest(){Generator g=new Generator(new Random(139));CurriculumLimits limits=GlobalCurriculum.limits("england-primary-2021-v1",EquivalentFractionPictures.ID,3);List<String> recent=new ArrayList<>();Set<String> seen=new HashSet<>();for(int i=0;i<156;i++){Question q=g.next(EquivalentFractionPictures.ID,recent,false,limits);assertTrue(seen.add(q.signature()));assertNotNull(EquivalentFractionPictures.read(q));recent.add(q.signature());}assertEquals(recent.get(0),g.next(EquivalentFractionPictures.ID,recent,false,limits).signature());}
 @Test public void malformedNonintegralAndAmbiguousConditionsIgnoreHiddenAnswers(){for(String equation:List.of("1/3 = □/4","1/2 = □/□","0/2 = □/4","2/2 = □/4","1/2 = 1/□","1/13 = □/2","1/2 = 2/4","1/2 = □/4 junk")){Question q=new Question(EquivalentFractionPictures.ID,EquivalentFractionPictures.PREFIX+equation,"0","0");assertNull(EquivalentFractionPictures.read(q));assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("0")).status);}}
}
